import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  random,
} from '../remotionShim';
// Pre-calculate deterministic base histogram distribution (120 bins)
// This simulates a typical image exposure distribution (mid-low heavy).
const BINS_COUNT = 120;
const sourceBins = new Array(BINS_COUNT).fill(0);
for (let i = 0; i < BINS_COUNT; i++) {
  const x = i / (BINS_COUNT - 1);
  // Generate three Gaussian peaks
  let val =
    0.6 * Math.exp(-Math.pow(x - 0.25, 2) / 0.01) +
    0.8 * Math.exp(-Math.pow(x - 0.45, 2) / 0.03) +
    0.2 * Math.exp(-Math.pow(x - 0.65, 2) / 0.015);
  // Add deterministic noise
  val += random(`noise-${i}`) * 0.15;
  sourceBins[i] = Math.max(0, val);
}



export type CameraHistogramProps = Record<string, any>;

const CameraHistogram: React.FC<CameraHistogramProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 10,
  uiColor = "#ffffff",
  shadowColor = "#444444",
  midtoneColor = "#888888",
  highlightColor = "#cccccc",
  showCameraOverlay = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // ANIMATION LOGIC
  // 1. Enter Animation
  const introProgress = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 80 },
    durationInFrames: fps * 1.5,
  });

  // 2. Exposure Shift (Simulates user increasing exposure, pushing histogram right)
  const shiftAmount = interpolate(
    frame,
    [fps * 2.5, fps * 5, fps * 7, fps * 9],
    [0, 35, 35, 5], // Shifts bins by this index amount
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Re-calculate bins for the current frame to simulate accurate highlight clipping
  const currentBins = useMemo(() => {
    const bins = new Array(BINS_COUNT).fill(0);
    for (let i = 0; i < BINS_COUNT; i++) {
      const newPos = i + shiftAmount;
      if (newPos >= BINS_COUNT - 1) {
        // Highlight clipping (stacks on the far right edge)
        bins[BINS_COUNT - 1] += sourceBins[i];
      } else if (newPos <= 0) {
        // Shadow clipping (stacks on the far left edge)
        bins[0] += sourceBins[i];
      } else {
        const lower = Math.floor(newPos);
        const upper = Math.ceil(newPos);
        const frac = newPos - lower;
        bins[lower] += sourceBins[i] * (1 - frac);
        if (upper < BINS_COUNT) {
          bins[upper] += sourceBins[i] * frac;
        }
      }
    }
    return bins;
  }, [shiftAmount]);

  // SVG dimensions
  const boxWidth = width * 0.65;
  const boxHeight = height * 0.45;

  // Generate SVG Path
  const maxVal = 2.2; // Scaling factor for peak heights
  let pathData = `M 0 ${boxHeight}`;
  const dx = boxWidth / (BINS_COUNT - 1);

  for (let i = 0; i < BINS_COUNT; i++) {
    const h = (currentBins[i] / maxVal) * boxHeight * introProgress;
    const clampedH = Math.min(boxHeight, h);
    pathData += ` L ${i * dx} ${boxHeight - clampedH}`;
  }
  pathData += ` L ${boxWidth} ${boxHeight} Z`;

  // UI calculations
  const isRecording = Math.sin(frame / 5) > 0;
  const evValue = (shiftAmount / 15).toFixed(1);
  const pad = (n: number) => n.toString().padStart(2, "0");
  const timecode = `00:00:${pad(Math.floor(frame / fps))}:${pad(frame % fps)}`;
  
  // Highlight clipping warning indicator opacity
  const clippingWarning = interpolate(currentBins[BINS_COUNT - 1], [0.5, 1.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Helvetica, Arial, sans-serif",
        fontWeight: "bold",
        color: uiColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* CAMERA UI OVERLAY */}
      {showCameraOverlay && (
        <AbsoluteFill style={{ padding: width * 0.05, opacity: introProgress }}>
          {/* Top Bar */}
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: width * 0.015, fontWeight: "bold" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div
                style={{
                  width: width * 0.012,
                  height: width * 0.012,
                  borderRadius: "50%",
                  backgroundColor: "#ef4444",
                  opacity: isRecording ? 1 : 0,
                }}
              />
              <span>REC</span>
              <span style={{ marginLeft: 20, opacity: 0.8 }}>{timecode}</span>
            </div>
            <div>BAT 100%</div>
          </div>

          {/* Center Brackets */}
          <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)", width: width * 0.8, height: height * 0.8, border: `2px solid ${uiColor}33` }}>
            <div style={{ position: "absolute", top: -2, left: -2, width: 40, height: 40, borderTop: `4px solid ${uiColor}`, borderLeft: `4px solid ${uiColor}` }} />
            <div style={{ position: "absolute", top: -2, right: -2, width: 40, height: 40, borderTop: `4px solid ${uiColor}`, borderRight: `4px solid ${uiColor}` }} />
            <div style={{ position: "absolute", bottom: -2, left: -2, width: 40, height: 40, borderBottom: `4px solid ${uiColor}`, borderLeft: `4px solid ${uiColor}` }} />
            <div style={{ position: "absolute", bottom: -2, right: -2, width: 40, height: 40, borderBottom: `4px solid ${uiColor}`, borderRight: `4px solid ${uiColor}` }} />
          </div>

          {/* Bottom Bar */}
          <div style={{ position: "absolute", bottom: width * 0.05, left: width * 0.05, right: width * 0.05, display: "flex", justifyContent: "space-between", fontSize: width * 0.018, fontWeight: "bold" }}>
            <div style={{ display: "flex", gap: 40 }}>
              <span>ISO AUTO</span>
              <span>f/2.8</span>
              <span>1/48</span>
            </div>
            <div style={{ display: "flex", gap: 40 }}>
              <span>5600K</span>
              <span style={{ color: Number(evValue) > 1.5 ? highlightColor : uiColor }}>
                EV +{evValue}
              </span>
            </div>
          </div>
        </AbsoluteFill>
      )}

      {/* HISTOGRAM CONTAINER */}
      <div
        style={{
          width: boxWidth,
          display: "flex",
          flexDirection: "column",
          gap: 20,
          opacity: introProgress,
          transform: `scale(${interpolate(introProgress, [0, 1], [0.95, 1])})`,
        }}
      >
        {/* Title / Description */}
        <div style={{ textAlign: "center", marginBottom: 20 }}>
          <h1 style={{ margin: 0, fontSize: width * 0.025, fontWeight: "bold", letterSpacing: 2 }}>
            LUMA HISTOGRAM
          </h1>
          <p style={{ margin: "10px 0 0 0", fontSize: width * 0.012, opacity: 0.6 }}>
            Exposure Distribution Map
          </p>
        </div>

        {/* The Graph */}
        <div
          style={{
            position: "relative",
            width: boxWidth,
            height: boxHeight,
            backgroundColor: `${uiColor}11`,
            border: `2px solid ${uiColor}44`,
            borderRadius: 8,
            overflow: "hidden",
            boxShadow: "0 20px 50px rgba(0,0,0,0.5)",
          }}
        >
          {/* Grid Background */}
          <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
            <line x1="25%" y1="0" x2="25%" y2="100%" stroke={`${uiColor}33`} strokeWidth="2" strokeDasharray="4 4" />
            <line x1="50%" y1="0" x2="50%" y2="100%" stroke={`${uiColor}33`} strokeWidth="2" strokeDasharray="4 4" />
            <line x1="75%" y1="0" x2="75%" y2="100%" stroke={`${uiColor}33`} strokeWidth="2" strokeDasharray="4 4" />
          </svg>

          {/* Histogram Data Path */}
          <svg
            width={boxWidth}
            height={boxHeight}
            viewBox={`0 0 ${boxWidth} ${boxHeight}`}
            style={{ position: "absolute", bottom: 0, left: 0 }}
          >
            <defs>
              <linearGradient id="histGradient" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor={shadowColor} stopOpacity="0.8" />
                <stop offset="25%" stopColor={shadowColor} stopOpacity="0.8" />
                <stop offset="45%" stopColor={midtoneColor} stopOpacity="0.8" />
                <stop offset="55%" stopColor={midtoneColor} stopOpacity="0.8" />
                <stop offset="75%" stopColor={highlightColor} stopOpacity="0.8" />
                <stop offset="100%" stopColor={highlightColor} stopOpacity="0.8" />
              </linearGradient>
            </defs>
            <path
              d={pathData}
              fill="url(#histGradient)"
              stroke={uiColor}
              strokeWidth="2"
              strokeLinejoin="round"
            />
          </svg>

          {/* Highlight Clipping Warning Strip */}
          <div
            style={{
              position: "absolute",
              top: 0,
              right: 0,
              bottom: 0,
              width: 6,
              backgroundColor: highlightColor,
              opacity: clippingWarning,
            }}
          />
        </div>

        {/* Labels Map */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            width: "100%",
            fontSize: width * 0.013,
            fontWeight: "bold",
            marginTop: 10,
          }}
        >
          <div style={{ color: shadowColor, display: "flex", flexDirection: "column", alignItems: "flex-start", flex: 1 }}>
            <span>← SHADOWS</span>
            <span style={{ fontSize: width * 0.009, opacity: 0.8, fontWeight: "bold", marginTop: 4 }}>Darker Pixels</span>
          </div>
          
          <div style={{ color: midtoneColor, display: "flex", flexDirection: "column", alignItems: "center", flex: 1 }}>
            <span>MIDTONES</span>
            <span style={{ fontSize: width * 0.009, opacity: 0.8, fontWeight: "bold", marginTop: 4 }}>Proper Exposure</span>
          </div>
          
          <div style={{ color: highlightColor, display: "flex", flexDirection: "column", alignItems: "flex-end", flex: 1 }}>
            <span>HIGHLIGHTS →</span>
            <span style={{ fontSize: width * 0.009, opacity: 0.8, fontWeight: "bold", marginTop: 4 }}>Brighter Pixels</span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CameraHistogram;